package io.invenlio.sales;
import java.math.BigDecimal;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class SalesFulfillmentAccessService implements SalesFulfillmentAccess{private final JdbcTemplate db;SalesFulfillmentAccessService(JdbcTemplate d){db=d;}@Override@Transactional(readOnly=true)public Order requireAllocated(UUID t,UUID id){var rows=db.query("SELECT id,sales_order_number,fulfillment_warehouse_id,fulfillment_status FROM sales_orders WHERE tenant_id=? AND id=? AND status IN('ALLOCATED','PARTIALLY_ALLOCATED')",(r,n)->new Object[]{r.getObject(1),r.getString(2),r.getObject(3),r.getString(4)},t,id);if(rows.isEmpty()){Integer visible=db.queryForObject("SELECT count(*) FROM sales_orders WHERE tenant_id=? AND id=?",Integer.class,t,id);throw visible==null||visible==0?new SalesException("SALES_ORDER_NOT_FOUND","Sales order not found"):new SalesException("SALES_ORDER_NOT_ALLOCATED","Allocated sales order required");}var x=rows.getFirst();var a=db.query("SELECT sales_order_line_id,inventory_reservation_id,allocated_quantity FROM sales_allocations WHERE tenant_id=? AND sales_order_id=? AND status='ACTIVE' ORDER BY sales_order_line_id,id",(r,n)->new Allocation((UUID)r.getObject(1),(UUID)r.getObject(2),r.getBigDecimal(3)),t,id);return new Order((UUID)x[0],(String)x[1],(UUID)x[2],(String)x[3],a);}@Override@Transactional public void pickingStarted(UUID t,UUID o){db.update("UPDATE sales_orders SET fulfillment_status='PICKING',updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND fulfillment_status='NOT_STARTED'",t,o);}@Override@Transactional public void picked(UUID t,UUID o,UUID l,BigDecimal q,boolean complete){db.update("UPDATE sales_order_lines SET picked_quantity=picked_quantity+?,updated_at=now(),version=version+1 WHERE tenant_id=? AND sales_order_id=? AND id=? AND picked_quantity+?<=allocated_quantity",q,t,o,l,q);if(complete)db.update("UPDATE sales_orders SET fulfillment_status='PICKED',updated_at=now(),version=version+1 WHERE tenant_id=? AND id=?",t,o);}@Override@Transactional public void packingStarted(UUID t,UUID o){db.update("UPDATE sales_orders SET fulfillment_status='PACKING',updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND fulfillment_status='PICKED'",t,o);}@Override@Transactional public void packed(UUID t,UUID o,Map<UUID,BigDecimal> qs){qs.forEach((l,q)->db.update("UPDATE sales_order_lines SET packed_quantity=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND sales_order_id=? AND id=? AND ?<=picked_quantity",q,t,o,l,q));db.update("UPDATE sales_orders SET fulfillment_status='PACKED',updated_at=now(),version=version+1 WHERE tenant_id=? AND id=?",t,o);}}
